from pathlib import Path
import json,collections,hashlib,sys
root=Path(sys.argv[1]) if len(sys.argv)>1 else Path('/tmp/bird-sticker-research')
a=json.loads((root/'data/species.json').read_text())['species'];tree=json.loads((root/'tree.json').read_text());paths={x['path']for x in tree['tree']if x['type']=='blob'and x['path'].startswith('stickers/')};files=[x['sticker']['file']for x in a]
assert not tree['truncated'] and len(a)==len(set(x['id']for x in a))==11064
assert len(set(files))==len(paths)==11064 and set(files)==paths
bykind=collections.Counter(x['sticker']['kind']for x in a)
ref=collections.Counter(str(x['sticker'].get('reference',{}).get('license'))for x in a if x['sticker']['kind']=='ai-illustration')
hero=json.loads((root/'previews/hero.json').read_text());lookup={x['id']:x for x in a}
result={'commit':json.loads((root/'commit.json').read_text())['sha'],'records':len(a),'uniqueIds':len(set(x['id']for x in a)),'stickerPathsMatched':len(paths),'orders':len(set(x['taxonomy']['order']for x in a)),'families':len(set(x['taxonomy']['family']for x in a)),'kinds':dict(bykind),'qualityPass':sum(bool(x['sticker']['meetsQualityBar'])for x in a),'qualityFail':sum(not x['sticker']['meetsQualityBar']for x in a),'names':{'en':sum(bool(x['names'].get('en'))for x in a),'zhHans':sum(bool(x['names'].get('zh-Hans'))for x in a),'languageColumns':len(json.loads((root/'data/languages.json').read_text()))},'aiScores':{'below70':sum(x['sticker']['reviewScore']<70 for x in a if x['sticker']['kind']=='ai-illustration'),'70to79':sum(70<=x['sticker']['reviewScore']<80 for x in a if x['sticker']['kind']=='ai-illustration'),'atLeast80ButFailed':sum(x['sticker']['reviewScore']>=80 and not x['sticker']['meetsQualityBar']for x in a if x['sticker']['kind']=='ai-illustration')},'referencesByRecordedLicense':dict(ref),'hero':{'count':len(hero),'kinds':dict(collections.Counter(lookup[i]['sticker']['kind']for i in hero)),'allMeetQualityBar':all(lookup[i]['sticker']['meetsQualityBar']for i in hero)},'methodLimits':['Checks metadata and Git tree paths, not all11064imagebytes','No independent ornithological or image-to-reference assessment','Author reviewScore/meetsQualityBar are recorded judgments, not calibrated accuracy probabilities'],'sourceSha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest()for n in ['data/species.json','data/languages.json','data/field-guide.zh-Hans.json','LICENSE.md','NOTICE.md']}}
assert result['orders']==44 and result['families']==250 and result['qualityPass']==7676 and result['qualityFail']==3388
out=Path(__file__).with_name('dataset-audit.json');out.write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps({k:v for k,v in result.items()if k not in ['referencesByRecordedLicense','sourceSha256']},ensure_ascii=False))
